import{_ as t,o as a,c as r,ah as o}from"./chunks/framework.CRsDMGp2.js";const m=JSON.parse('{"title":"Guide — Partenaire","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"guide/partenaire.md","filePath":"src/guide/partenaire.md"}'),n={name:"guide/partenaire.md"};function i(s,e,u,c,l,d){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="guide-—-partenaire" tabindex="-1">Guide — Partenaire <a class="header-anchor" href="#guide-—-partenaire" aria-label="Permalink to &quot;Guide — Partenaire&quot;">​</a></h1><p>Réaliser vos tâches et suivre votre rémunération.</p><h2 id="bienvenue-sur-naia" tabindex="-1">Bienvenue sur Naia <a class="header-anchor" href="#bienvenue-sur-naia" aria-label="Permalink to &quot;Bienvenue sur Naia&quot;">​</a></h2><p>Vous avez été invité par un chef de projet à intervenir sur un ou plusieurs projets, avec un accès limité aux tâches qui vous concernent — vous ne voyez pas l&#39;ensemble du projet comme le ferait le client ou le chef de projet.</p><h2 id="vos-taches" tabindex="-1">Vos tâches <a class="header-anchor" href="#vos-taches" aria-label="Permalink to &quot;Vos tâches&quot;">​</a></h2><p>Votre tableau de bord et l&#39;onglet <strong>Tâches</strong> de chaque projet regroupent les missions qui vous sont confiées :</p><ul><li>consultez les tâches et spécifications qui vous concernent, tous projets confondus ;</li><li>mettez à jour leur avancement (à faire, en cours, terminée) et déposez vos livrables directement depuis leur fiche.</li></ul><h2 id="votre-remuneration" tabindex="-1">Votre rémunération <a class="header-anchor" href="#votre-remuneration" aria-label="Permalink to &quot;Votre rémunération&quot;">​</a></h2><p>Les modalités de votre rémunération (forfait, pourcentage d&#39;un jalon ou taux journalier) sont convenues avec le chef de projet pour chaque projet — reportez-vous à votre contrat de prestation de services pour le détail.</p><ul><li>Déposez votre propre facture pour la rémunération convenue depuis l&#39;onglet <strong>Paiements partenaires</strong> du projet concerné.</li><li>Suivez le statut de votre paiement (dû ou versé) directement depuis cet onglet — c&#39;est l&#39;administrateur qui enregistre le règlement une fois celui-ci effectué.</li></ul><h2 id="communication" tabindex="-1">Communication <a class="header-anchor" href="#communication" aria-label="Permalink to &quot;Communication&quot;">​</a></h2><p>Échangez avec l&#39;équipe interne via la messagerie intégrée ou les commentaires de tâche. Vous êtes notifié des validations, retours ou nouvelles échéances.</p><div class="warning custom-block"><p class="custom-block-title">Projet bloqué pour impayé</p><p>Si un projet est bloqué pour impayé côté client, vous en êtes notifié. Vous pouvez terminer une tâche déjà démarrée, mais pas en démarrer une nouvelle avant le déblocage. Vous gardez l&#39;accès au projet, à vos documents et à la messagerie.</p></div>',13)])])}const v=t(n,[["render",i]]);export{m as __pageData,v as default};
